/* The warm-editorial design system, written in logical properties throughout: the same
   sheet lays the page out right-to-left for Hebrew and left-to-right for English, because
   direction follows the content's language rather than a site-wide setting. */
@import './fonts.GENERATED.css';

:root {
  --paper: #f6f3ec;
  --card: #fdfcf8;
  --tint: #f1ede2;
  --ink: #201e19;
  --muted: #6e685c;
  --rule: #e2dccc;
  --oxide: #9b2c20;
  --oxide-deep: #6e1d14;
  --oxide-light: #d98a80;
  --amber: #a97a1f;

  --serif: 'Frank Ruhl Libre', Georgia, 'Times New Roman', serif;
  --sans: 'Heebo', 'Helvetica Neue', Arial, sans-serif;

  --page: 1120px;
  --gap: 24px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--oxide);
  text-decoration: none;
}

a:hover {
  color: var(--oxide-deep);
  text-decoration: underline;
}

.page {
  max-width: var(--page);
  margin: 0 auto;
  padding: 0 32px;
}

/* ---- chrome ---------------------------------------------------------------- */

.masthead {
  border-block-end: 1px solid var(--ink);
}

.masthead__inner {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--gap);
  padding: 20px 0 12px;
}

.masthead__rule {
  border-block-start: 2px solid var(--ink);
  height: 3px;
}

