1	// The screen lane: the built site and the shipped Worker, driven in a pinned Chromium.
2	// The expected result of each case is the committed image below its leaf in
3	// requirements.md — approving that picture is approving the page.
4	import test, { after } from 'node:test';
5	import { build } from 'vite';
6	import { createTestHarness } from 'wrangler';
7	import type { Page } from 'playwright-core';
8	import { goldenPath, loadCase, readCases, type CaseFile } from '../registry.ts';
9	import { resetAndMigrate } from '../shared/migrations.ts';
10	import { harnessConfigPath } from '../shared/worker-config.ts';
11	import { corpusOn, seedCorpus, type SeededCorpus } from '../shared/fixtures.ts';
12	import type { D1Database } from '../../../src/backend/env.ts';
13	import type { OperationsView } from '../../../src/shared/api.ts';
14	import { DASHBOARD, DESKTOP, launchBrowser, newContext, settle, SITE, type App, type Viewport } from './harness.ts';
15	import { compareWithGolden, refreshing } from './compare.ts';
16	
17	export type ScreenContext = {
18	  /** Opens a site path and waits until the page itself says it has rendered. */
19	  open(path: string, viewport?: Viewport): Promise<Page>;
20	  /** The same, for the operator console — a separate artifact on its own origin. */
21	  openDashboard(path: string, viewport?: Viewport): Promise<Page>;
22	  /**
23	   * Installs the operations payload the next page will read. The shipped Worker in this
24	   * lane has no DASHBOARD_TOKEN — a secret is not in the committed config — so a case
25	   * that wants to look at a crawl builds the view from the shipped code and serves it.
26	   */
27	  serveOperations(view: OperationsView | null): void;
28	  /**
29	   * Captures the page and compares it with this case's committed golden. A selector
30	   * narrows the capture to that element's box, for a leaf about one piece of the page
31	   * rather than the whole of it.
32	   */
33	  shoot(page: Page, within?: string): Promise<void>;
34	  seeded: SeededCorpus;
35	};
36	
37	// Both apps, each built the way its own deploy builds it.
38	for (const app of [SITE, DASHBOARD]) await build({ configFile: app.config, logLevel: 'warn' });
39	
40	const server = createTestHarness({ workers: [{ configPath: harnessConfigPath() }] });
41	await server.listen();
42	const env = await server.getWorker<{ CORPUS: D1Database }>().getEnv();
43	await resetAndMigrate(env.CORPUS);
44	const seeded = await seedCorpus(corpusOn(env.CORPUS));
45	
46	const browser = await launchBrowser();
47	after(async () => {
48	  await browser.close();
49	  await server.close();
50	});
51	
52	const api = async (pathAndQuery: string) => {
53	  const response = await server.fetch(pathAndQuery);
54	  return {
55	    status: response.status,
56	    headers: { 'content-type': response.headers.get('content-type') ?? 'application/json' },
57	    body: await response.text(),
58	  };
59	};
60	
61	/** An element's box in document coordinates — viewport coordinates go stale on a scroll. */
62	async function documentBox(page: Page, selector: string): Promise<{ x: number; y: number; width: number; height: number }> {
63	  const box = await page.evaluate((css) => {
64	    const element = document.querySelector(css);
65	    if (!element) return null;
66	    const rect = element.getBoundingClientRect();
67	    return { x: rect.x + window.scrollX, y: rect.y + window.scrollY, width: rect.width, height: rect.height };
68	  }, selector);
69	  if (!box) throw new Error(`nothing matched ${selector}, so there is nothing to capture`);
70	  const x = Math.floor(box.x);
71	  const y = Math.floor(box.y);
72	  return { x, y, width: Math.ceil(box.x + box.width) - x, height: Math.ceil(box.y + box.height) - y };
73	}
74	
75	async function screenContext(caseFile: CaseFile): Promise<ScreenContext> {
76	  const pages: Page[] = [];
77	  let operations: OperationsView | null = null;
78	
79	  const answer = async (pathAndQuery: string) => {
80	    if (operations && pathAndQuery.startsWith('/api/v1/operations')) {
81	      return { status: 200, headers: { 'content-type': 'application/json' }, body: JSON.stringify(operations) };
82	    }
83	    return api(pathAndQuery);
84	  };
85	
86	  const openOn = async (app: App, sitePath: string, viewport: Viewport) => {
87	    // A fresh context per capture — state must not leak between cases — while the
88	    // browser itself is launched once, because process startup dominates the cost.
89	    const context = await newContext(browser, answer, viewport, app);
90	    const page = await context.newPage();
91	    pages.push(page);
92	    // A page that fails to render is a blank screenshot and a timeout; whatever the
93	    // page itself said about why is the only thing that explains it.
94	    page.on('pageerror', (error) => console.error(`${caseFile.id} page error: ${error.message}`));
95	    page.on('requestfailed', (request) =>
96	      console.error(`${caseFile.id} request failed: ${request.url()} ${request.failure()?.errorText ?? ''}`),
97	    );
98	    await page.goto(`${app.origin}${sitePath}`, { waitUntil: 'commit' });
99	    await settle(page);
100	    return page;
101	  };
102	
103	  return {
104	    seeded,
105	    serveOperations(view) {
106	      operations = view;
107	    },
108	    open: (sitePath, viewport = DESKTOP) => openOn(SITE, sitePath, viewport),
109	    openDashboard: (sitePath, viewport = DESKTOP) => openOn(DASHBOARD, sitePath, viewport),
110	    async shoot(page: Page, within?: string) {
111	      // The clip comes off the full-page shot rather than off the element: an element
112	      // screenshot scrolls the element into view first, and a scroll dismisses whatever
113	      // state the case opened. Whole pixels, because a fractional clip leaves the
114	      // rounding to the renderer and half a pixel either way is a different image.
115	      const clip = within ? await documentBox(page, within) : undefined;
116	      const shot = await page.screenshot({ fullPage: true, animations: 'disabled', clip });
117	      const outcome = compareWithGolden(shot, goldenPath(caseFile), `${caseFile.slug}.${caseFile.id}`);
118	      if (outcome === 'written') console.log(`${caseFile.id}: wrote ${caseFile.golden} — review it in the diff`);
119	      await page.context().close();
120	    },
121	  };
122	}
123	
124	// One at a time, on purpose. Registered as separate top-level tests these run together,
125	// and eight browser contexts rendering at once on one machine starve each other until
126	// most of them miss the ready signal — which reads exactly like a broken page.
127	test('screen', async (lane) => {
128	  for (const caseFile of readCases('screen')) {
129	    const screenCase = await loadCase<ScreenContext>(caseFile);
130	    await lane.test(`${caseFile.id} — ${screenCase.title}`, async () => {
131	      await screenCase.run(await screenContext(caseFile));
132	    });
133	  }
134	});
135	
136	if (refreshing()) console.log('goldens refreshed: review every changed image before committing it');

